DECLINE = "عذراً، لا تتوفر لدي معلومات عن %s. أستطيع المساعدة فقط في خدمات جواز السفر ودفتر العائلة والبطاقة الذكية."


def M(q, typ, services, must, ref, ctx, must_not=(), status="ok", note=None, any_of=False):
    m = {
        "question": q,
        "type": typ,
        "expect_status": status,
        "expect_services": list(services),
        "must_include": list(must),
        "must_not_include": list(must_not),
        "ref_answer": ref,
        "ref_contexts": [S[k] for k in ctx],
    }
    if any_of:
        m["expect_any"] = True  # any ONE of expect_services is enough for "covers"
    if note:
        m["note"] = note
    return m


def OOS(q, topic, must_not=(), note=None, typ="not_in_data"):
    return M(q, typ, [], [], DECLINE % topic, [], must_not, status="out_of_scope", note=note)


def UNC(q, ref, note=None, typ="unclear"):
    return M(q, typ, [], [], ref, [], status="unclear", note=note)


