def build():
    chats = []
    for i, msgs in enumerate(CHATS, 1):
        cid = "dev-%02d" % i
        out = []
        for j, m in enumerate(msgs, 1):
            d = {"message_id": "%s-%d" % (cid, j)}
            d.update(m)
            out.append(d)
        chats.append({"chat_id": cid, "messages": out})
    return {"chats": chats}


if __name__ == "__main__":
    data = build()
    path = os.path.join(HERE, "dev_set.json")
    with open(path, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
    n = sum(len(c["messages"]) for c in data["chats"])
    print("wrote %s: %d chats, %d messages" % (path, len(data["chats"]), n))
